191 static inline int LuaZoneBeginS( lua_State* L )
192 {
193 #ifdef TRACY_ON_DEMAND
194     const auto zoneCnt = GetLuaZoneState().counter++;
195     if( zoneCnt != 0 && !GetLuaZoneState().active ) return 0;
196     GetLuaZoneState().active = GetProfiler().IsConnected();
197     if( !GetLuaZoneState().active ) return 0;
198 #endif
199 
200 #ifdef TRACY_CALLSTACK
201     const uint32_t depth = TRACY_CALLSTACK;
202 #else
203     const auto depth = uint32_t( lua_tointeger( L, 1 ) );
204 #endif
205     SendLuaCallstack( L, depth );
206 
207     lua_Debug dbg;
208     lua_getstack( L, 1, &dbg );
209     lua_getinfo( L, "Snl", &dbg );
210     const auto srcloc = Profiler::AllocSourceLocation( dbg.currentline, dbg.source, dbg.name ? dbg.name : dbg.short_src );
211 
212     TracyQueuePrepare( QueueType::ZoneBeginAllocSrcLocCallstack );
213     MemWrite( &item->zoneBegin.time, Profiler::GetTime() );
214     MemWrite( &item->zoneBegin.srcloc, srcloc );
215     TracyQueueCommit( zoneBeginThread );
216 
217     return 0;
218 }
219 
220 static inline int LuaZoneBeginNS( lua_State* L )
