304 static inline int LuaZoneEnd( lua_State* L )
305 {
306 #ifdef TRACY_ON_DEMAND
307     assert( GetLuaZoneState().counter != 0 );
308     GetLuaZoneState().counter--;
309     if( !GetLuaZoneState().active ) return 0;
310     if( !GetProfiler().IsConnected() )
311     {
312         GetLuaZoneState().active = false;
313         return 0;
314     }
315 #endif
316 
317     TracyQueuePrepare( QueueType::ZoneEnd );
318     MemWrite( &item->zoneEnd.time, Profiler::GetTime() );
319     TracyQueueCommit( zoneEndThread );
320     return 0;
321 }
