323 static inline int LuaZoneText( lua_State* L )
324 {
325 #ifdef TRACY_ON_DEMAND
326     if( !GetLuaZoneState().active ) return 0;
327     if( !GetProfiler().IsConnected() )
328     {
329         GetLuaZoneState().active = false;
330         return 0;
331     }
332 #endif
333 
334     auto txt = lua_tostring( L, 1 );
335     const auto size = strlen( txt );
336     assert( size < (std::numeric_limits<uint16_t>::max)() );
337 
338     auto ptr = (char*)tracy_malloc( size );
339     memcpy( ptr, txt, size );
340 
341     TracyQueuePrepare( QueueType::ZoneText );
342     MemWrite( &item->zoneTextFat.text, (uint64_t)ptr );
343     MemWrite( &item->zoneTextFat.size, (uint16_t)size );
344     TracyQueueCommit( zoneTextFatThread );
345     return 0;
346 }
